add('응답 처리','Java 객체가 JSON 응답이 되는 과정',linear('응답 DTO를 메시지 변환기가 JSON으로 쓰고 클라이언트로 전달합니다',[('응답 DTO','보여줄 상품 데이터'),('메시지 변환기','Java 객체 → JSON'),('HTTP 응답','상태·헤더·본문')])+call('JSON 응답에서는 메시지 변환기가 Jackson을 이용해 객체를 JSON으로 씁니다.<br>정상·실패 결과 모두 클라이언트가 이해할 수 있어야 합니다.'),note='JSON 응답 본문은 직접 문자열을 이어붙여 만드는 방식으로 설명하지 않습니다. @ResponseBody 또는 @RestController의 반환값 처리를 통해 메시지 변환기가 응답 본문을 씁니다. 메시지 변환기의 인코딩·미디어 타입 협상 세부 사항은 추가 질문이 있을 때만 다룹니다.')
add('Spring MVC','화면 반환과 응답 본문 반환',table([['사용 방식','반환값이 쓰이는 곳'],['@Controller의 화면 처리','뷰 이름과 데이터를 이용해 HTML 화면 렌더링'],['@RestController','반환값을 메시지 변환기로 응답 본문에 쓰기'],['@Controller + @ResponseBody','해당 메서드의 반환값을 응답 본문에 쓰기']])+call('상품 API에서는 화면 이름 대신 상품 데이터를 JSON 본문으로 반환합니다.'),note='@Controller가 항상 HTML만 반환한다고 단정하지 않습니다. 문자열 반환도 @ResponseBody 유무에 따라 의미가 달라집니다. JSON API에서는 보통 ViewResolver를 거쳐 HTML 템플릿을 찾는 흐름이 사용되지 않는다는 점을 설명합니다.')
add('교재 CH 09','요청 DTO · 도메인 · 응답 DTO',table([['객체','담당할 데이터와 규칙'],['CreateProductRequest','외부 요청의 name·price와 입력 조건'],['Product','상품 id·이름·가격과 상품 자체의 규칙'],['ProductResponse','응답으로 공개할 id·이름·가격']])+call('외부 입력 형식이 바뀌는 일과 상품의 업무 규칙이 바뀌는 일을 분리합니다.'),note='새 DTO 작성 실습을 길게 반복하지 않고 교재 9장의 코드와 현재 구현을 대조합니다. DTO가 도메인의 모든 필드를 그대로 받을 필요는 없습니다. 예를 들어 상품 id는 서버가 부여하며 생성 요청의 임의 id를 그대로 신뢰하는 구조로 설명하지 않습니다.')
add('REST 응답','ResponseEntity의 상태·헤더·본문',table([['응답 구성','상품 생성 응답 예'],['상태 코드','201 Created · 새 상품 생성'],['헤더','Location: /products/생성된-id'],['본문','생성한 상품의 id·name·price JSON']])+call('ResponseEntity로 응답의 세 부분을 함께 정합니다.<br>Location과 조회에는 실제 생성 결과의 id를 사용합니다.'),note='교재 상품 추가 Controller와 수업 참고 ProductController를 함께 봅니다. id가 1부터 시작하거나 연속된다고 가정하지 않습니다. ResponseEntity를 사용해야만 모든 JSON 응답이 가능하다고 설명하지 않습니다. 일반 응답 DTO 반환도 가능합니다.')
add('REST 응답','정상 응답과 실패 응답 구분',table([['상태 코드','오늘 상품 API에서의 의미'],['200 / 201','조회 성공 / 상품 생성 성공'],['400 / 404','잘못된 입력 / 조회할 상품이 없음'],['500','예상하지 못한 서버 처리 오류']])+call('실패 이유에 맞게 상태와 본문을 함께 정합니다.<br>모든 예외를 400으로 바꾸면 서버 문제까지 입력 오류처럼 보입니다.'),note='이 표는 오늘 상품 API의 응답 설계 기준입니다. 없는 상품의 404는 해당 예외에 대한 매핑을 구현해야 합니다. 프레임워크가 모든 업무 예외를 알아서 400/404로 분류한다고 설명하지 않습니다. HTTP 메서드 전체와 REST 성숙도는 별도 긴 강의로 확장하지 않고 필요한 질문만 연결합니다.')
add('교재 CH 10','유효성 검사와 예외 처리',steps('도메인 객체와 Controller의 입력 검사','전역 예외 핸들러','HTTP 응답 상태 코드와 오류 본문')+call('세부 설명과 구현은 책의 10장을 보며 함께 진행합니다.'),note='교재 10장의 도메인 객체 및 컨트롤러 유효성 검사 추가하기, 전역 예외 핸들러 추가하기, HTTP 응답 상태 코드와 바디를 읽습니다. PPT는 핵심 구분만 짚고 세부 코드와 어노테이션 설정은 책으로 설명합니다. JSON 읽기나 요청 DTO 검증은 Controller 메서드 실행 전에 실패할 수 있습니다. 일반적인 예외는 MethodArgumentNotValidException·HttpMessageNotReadableException이며 모든 검증 경로가 같은 예외를 낸다고 설명하지 않습니다.')
add('유효성 검사','입력 검증과 업무 규칙',table([['위치','확인할 핵심'],['요청 DTO','이름 @NotBlank · 가격 Integer + @NotNull·@Min(0)'],['도메인 객체','이름·가격의 규칙 유지 · 앞뒤 공백 정리'],['Service','상품 존재 여부 등 업무 처리 조건 확인']])+call('요청 DTO는 @Valid로 검사합니다. 가격 누락은 거부하고 0원은 허용합니다.<br>요청 검증을 추가해도 도메인 객체의 규칙은 유지합니다.'),note='입력 형식 검사와 도메인의 유효한 상태·업무 처리 조건을 구분합니다. @NotBlank는 null·빈 문자열·공백뿐인 문자열을 거부하지만 값을 trim해서 바꾸지는 않습니다. 요청 가격은 Integer로 누락과 명시적인 0을 구분하고 @NotNull·@Min(0)을 함께 사용합니다. @Min만으로 null을 거부한다고 설명하지 않습니다. @Valid가 요청 DTO의 제약을 실행하며 도메인 객체는 HTTP 이외의 경로에서도 자신의 규칙을 지킵니다. 검증 적용 전 dependencies의 implementation "org.springframework.boot:spring-boot-starter-validation"과 Gradle 동기화, jakarta.validation import를 확인합니다. 서비스 메서드 @Validated 등은 필수가 아닙니다.')
add('예외 처리','실패 이유에 맞는 응답',table([['상황','오늘 상품 API의 응답 기준'],['잘못된 입력','400 · 입력을 고칠 수 있는 메시지'],['없는 상품','404 · 찾을 수 없다는 메시지'],['예상하지 못한 서버 오류','500 · 입력 오류와 구분']])+call('@RestControllerAdvice·@ExceptionHandler로 예외별 상태와 오류 본문을 정합니다.<br>모든 예외를 400으로 바꾸거나 내부 예외 정보를 그대로 보내지 않습니다.'),note='교재의 전역 예외 핸들러 부분을 보며 수업 참고 구현의 message 본문을 확인합니다. 요청 DTO 검증·JSON 읽기·수업 도메인의 입력 예외는 400, ProductNotFoundException은 404로 연결합니다. 업무 예외를 HTTP로 매핑하는 것은 애플리케이션 설계이며 프레임워크가 모든 업무 오류를 자동 분류하지 않습니다. 이 참고 핸들러가 모든 경로404·매개변수타입오류·예상하지못한500까지 같은message JSON을 보장하지 않습니다. 모든 IllegalArgumentException이 항상 클라이언트 오류라는 일반 규칙으로 설명하지 않습니다. 500을 catch(Exception)으로 잡아 모두400으로 바꾸지 않습니다. 내부 상세는 서버에서 진단하고 사용자용 오류에는 필요한 정보만 담습니다.')
add('QA 활동','QA 체크리스트 작성과 실행',steps('상품 API의 요구사항에서 확인할 항목 정리','사전 조건·입력·기대 결과·실제 결과·통과 여부 작성','직접 실행하고 발견한 문제 수정','다시 확인한 결과와 남은 문제를 README에 기록')+call('정상 동작·잘못된 입력·경계 조건·실패 시 데이터 유지를 포함합니다.<br>구체적인 입력값과 확인 순서는 직접 설계합니다.'),note='새 프로젝트를 만들지 않고 기존 product-api에서 짧게 수행합니다. 책의 검증과 예외 처리를 적용한 범위만 확인하며 정답 체크리스트를 배포하지 않습니다. Postman 또는 현재 사용 가능한 클라이언트를 이용합니다. 7일 단위·통합 테스트는 유지하되 새로운 테스트 코드 작성을 오늘 QA 활동의 필수 조건으로 만들지 않습니다. 상품 HTTP API 연결이 미완료라면 해당 범위를 먼저 마치고 실제 완료 수준을 기록합니다.')
add('개인 과제','위시리스트 유효성 검사',table([['입력·상황','지켜야 할 규칙'],['이름','null·빈 문자열·공백뿐인 이름 거부 · 앞뒤 공백 제거'],['가격','0 이상의 정수 · 무료 항목 0원 허용'],['예산·조회 id','음수 예산 거부 · 없는 id는 예외로 구분']])+call('기존 personal-project/의 검증을 유지하고 빠진 조건과 검사 위치를 보완합니다.<br>실패한 요청은 기존 데이터를 바꾸지 않아야 합니다.'),note='7일에 만든 위시리스트에 오늘 배운 검증 책임 분리를 적용하는 과제입니다. 이미 구현한 규칙을 지우거나 똑같이 다시 만들지 않습니다. Domain이 이름·가격을 지키고 Service가 예산과 존재 여부를 확인하도록 현재 코드를 점검해 누락된 부분을 보완합니다. 가격 0·예산 0 허용, 추천의 가격 정렬·동일 가격 등록 순서·최대 3개·원본 보존과 기존 테스트를 유지합니다. 새 프로젝트와 DB는 만들지 않습니다.')
add('개인 과제','검증 적용 범위와 제출',table([['항목','과제 내용'],['적용 범위','Domain·Service 검증 필수 · HTTP API가 있으면 요청 DTO와 실패 응답도 적용'],['QA·README','직접 체크리스트 작성·실행 · 검증 위치와 실제 결과 기록'],['Issue·PR 제목','[11/09][이름] 위시리스트 유효성 검사']])+call('기존 개인 Fork의 personal-project/에서 작업합니다. 새 HTTP API는 필수가 아닙니다.<br>공용 저장소에 이 과제의 Issue 1개·PR 1개로 코드와 README를 제출합니다.'),note='HTTP API가 이미 있는 경우에만 요청 DTO 이름에 @NotBlank, 가격은 Integer와 @NotNull·@Min(0), Controller 인자에 @Valid를 적용하고 적절한 400·404 응답을 연결합니다. HTTP가 없다면 Domain·Service에서 검증하며 어노테이션을 붙이는 것 자체를 완료 기준으로 삼지 않습니다. QA 항목은 정상·잘못된 입력·경계 조건·실패 시 데이터 보존을 고려해 교육생이 직접 설계합니다. README에는 검증을 맡긴 위치와 이유, 실행 결과·발견한 문제·수정 결과·남은 문제를 기록하고 기존 테스트를 유지합니다. 상품 API의 수업 중 QA 기록과 별개인 개인 과제 제출입니다. 기존 구현 브랜치에서 새 자율 이름의 브랜치를 만들고 개인 origin에 Push한 뒤 조직 원본 sesac-ddm-4-web/sesac-spring-boot-study의 main으로 PR을 올립니다. 이전 PR 링크와 이번 보완 범위를 적으며 리뷰 수정은 같은 브랜치에 Push합니다. 강사는 병합 없이 PR·Issue를 닫고 제출 브랜치를 보존합니다.')
add('시간이 남으면 · CH 11','데이터베이스 연동 도입',table([['읽을 곳','함께 볼 내용'],['1. DB를 사용하는 웹 애플리케이션','메모리 저장과 DB 저장의 차이'],['2. 데이터베이스 다뤄 보기','테이블·행·열·기본키와 간단한 SQL'],['다음 단계','상품 Repository가 DB에 저장·조회하도록 변경']])+call('오늘은 도입만 진행합니다. DB 연결과 전체 CRUD 구현은 별도 진도로 이어갑니다.'),note='발표와 MVC·검증 설명 후 시간이 남고 이해도가 충분할 때만 진행합니다. 프로세스 메모리는 재시작하면 초기화되고, DB 저장은 적절한 영구 저장 설정과 연결이 유지될 때 재시작 후 다시 읽을 수 있습니다. 모든 DB가 자동으로 영구 저장한다는 식으로 설명하지 않습니다. 교재 11장의 JDBC 접근과 이후 JPA 접근은 구분합니다. 오늘 JPA·Entity·N+1을 선행 강의하지 않습니다.')
add('GitHub 제출','공용 저장소에 학습 결과 제출',table([['항목','제출 방법'],['작업 위치','기존 개인 Fork의 product-api/ · 이전 구현 브랜치에서 이어가기'],['Issue·PR 제목','[11/09][이름] 상품 API 검증과 예외 처리'],['PR 본문','구현 범위·QA 결과·관련 Issue #번호·이전 PR 링크']])+call('코드와 README를 Issue 1개·PR 1개로 제출합니다. 브랜치 이름은 자율입니다.<br>설명만 들었다면 기록을 남기고, 변경이 생겼을 때 해당 범위를 제출합니다.'),note='조직 원본 https://github.com/sesac-ddm-4-web/sesac-spring-boot-study 에 Issue와 PR을 올립니다. base repository는 조직 원본, base는 main, head는 본인 Fork의 작업 브랜치입니다. 개인 origin에 Push하고 리뷰 수정도 같은 브랜치에 Push합니다. 원본 main에는 교육생 구현을 병합하지 않고 강사가 리뷰 후 PR·Issue를 닫습니다. 작업 브랜치는 보존하며 main을 pull해서 이전 개인 구현이 생긴다고 안내하지 않습니다. 라벨·담당자·마일스톤 관리 권한을 교육생에게 요구하지 않습니다. 실제 코드 변경이 없는 교육생에게 빈 PR을 강제하지 않습니다. greeting-api와 personal-project 및 기존 README 링크, Gradle Wrapper를 보존하고 빌드 결과물·IDE 파일·비밀값은 제외합니다.')
add('GitHub 제출','원본 PR 대상과 리뷰',table([['선택할 항목','설정할 값'],['base repository / base','sesac-ddm-4-web/sesac-spring-boot-study / main'],['head repository / compare','본인 계정의 Fork / 구현한 작업 브랜치'],['PR 생성 경로','원본 Pull requests → New pull request → compare across forks']])+call('리뷰 수정은 같은 브랜치에 Push합니다. 강사가 확인 후 병합 없이 PR·Issue를 닫습니다.<br>제출 브랜치는 보존하고, 이전 구현을 이어갈 때 해당 브랜치에서 시작합니다.'),note='개인 origin에 Push한 코드가 원본 PR의 head에 표시되는지 확인합니다. 원본 main에 교육생별 구현을 합치지 않습니다. 리뷰 전에 교육생이 PR을 닫거나 직접 병합하도록 안내하지 않습니다. 이전 제출 코드가 함께 포함되면 이전 PR 링크와 이번 변경 범위를 본문에 적습니다.')
